package uf_test

import (
	"testing"

	"github.com/ai-verification/go-unionfind/internal/uf"
)

func TestNewCount(t *testing.T) {
	dsu := uf.New(5)
	if dsu.Count() != 5 {
		t.Fatalf("expected Count=5, got %d", dsu.Count())
	}
}

func TestFindSelf(t *testing.T) {
	dsu := uf.New(4)
	for i := 0; i < 4; i++ {
		if dsu.Find(i) != i {
			t.Fatalf("Find(%d) should be %d before any unions", i, i)
		}
	}
}

func TestUnionAndConnected(t *testing.T) {
	dsu := uf.New(5)
	dsu.Union(0, 1)
	dsu.Union(2, 3)
	if !dsu.Connected(0, 1) {
		t.Fatal("0 and 1 should be connected after Union")
	}
	if dsu.Connected(0, 2) {
		t.Fatal("0 and 2 should not be connected")
	}
	if dsu.Connected(1, 4) {
		t.Fatal("1 and 4 should not be connected")
	}
}

func TestCountDecreases(t *testing.T) {
	dsu := uf.New(5)
	dsu.Union(0, 1) // 4 components
	dsu.Union(2, 3) // 3 components
	dsu.Union(0, 3) // 2 components (merges {0,1} and {2,3})
	if dsu.Count() != 2 {
		t.Fatalf("expected Count=2, got %d", dsu.Count())
	}
}

func TestUnionAlreadyConnected(t *testing.T) {
	dsu := uf.New(3)
	dsu.Union(0, 1)
	dsu.Union(0, 1) // second union should be a no-op on count
	if dsu.Count() != 2 {
		t.Fatalf("expected Count=2 after redundant Union, got %d", dsu.Count())
	}
}

func TestTransitiveConnectivity(t *testing.T) {
	dsu := uf.New(6)
	dsu.Union(0, 1)
	dsu.Union(1, 2)
	dsu.Union(3, 4)
	if !dsu.Connected(0, 2) {
		t.Fatal("0 and 2 should be connected transitively")
	}
	if dsu.Connected(0, 3) {
		t.Fatal("0 and 3 should not be connected")
	}
	if dsu.Count() != 3 {
		t.Fatalf("expected Count=3, got %d", dsu.Count())
	}
}
